"use client";
import { useEffect, useState } from "react";

interface GlitchTextProps {
    text: string;
    className?: string;
    style?: React.CSSProperties;
    /** replay the glitch-in animation whenever this flips */
    triggerKey?: string | number;
    as?: "span" | "h1" | "h2";
}

export function GlitchText({ text, className, style, triggerKey, as = "span" }: GlitchTextProps) {
    const [play, setPlay] = useState(true);
    const Tag = as as any;

    useEffect(() => {
        setPlay(false);
        const id = requestAnimationFrame(() => setPlay(true));
        return () => cancelAnimationFrame(id);
    }, [triggerKey, text]);

    return (
        <Tag
            className={className}
            data-text={text}
            style={{ ...style, position: "relative", display: "inline-block" }}
        >
            <span style={{ position: "relative", zIndex: 1 }}>{text}</span>
            {play && (
                <>
                    <span aria-hidden className="glitch-layer glitch-cyan">{text}</span>
                    <span aria-hidden className="glitch-layer glitch-red">{text}</span>
                </>
            )}
            <style jsx>{`
                .glitch-layer {
                    position: absolute;
                    left: 0;
                    top: 0;
                    width: 100%;
                    overflow: hidden;
                    opacity: 0.85;
                }
                .glitch-cyan {
                    color: var(--color-jedi-cyan, #5eead4);
                    animation: glitchShift 420ms steps(2, end) 1;
                    mix-blend-mode: screen;
                }
                .glitch-red {
                    color: var(--color-imperial-red);
                    animation: glitchShift 420ms steps(2, end) 1 reverse;
                    mix-blend-mode: screen;
                }
                @keyframes glitchShift {
                    0% { clip-path: inset(0 0 85% 0); transform: translate3d(-3px, 0, 0); }
                    20% { clip-path: inset(20% 0 60% 0); transform: translate3d(3px, 0, 0); }
                    40% { clip-path: inset(60% 0 5% 0); transform: translate3d(-2px, 0, 0); }
                    60% { clip-path: inset(10% 0 70% 0); transform: translate3d(2px, 0, 0); }
                    80% { clip-path: inset(75% 0 2% 0); transform: translate3d(-1px, 0, 0); }
                    100% { clip-path: inset(0 0 0 0); transform: translate3d(0, 0, 0); opacity: 0; }
                }
                @media (prefers-reduced-motion: reduce) {
                    .glitch-layer { display: none; }
                }
            `}</style>
        </Tag>
    );
}

"use client";

import { useRef } from "react";



interface HudFrameProps {

    children: React.ReactNode;

    accent: string; // css color/var

    active?: boolean; // pulses the border, e.g. while analyzing

    label?: string;

    status?: string;

    className?: string;

}



export function HudFrame({ children, accent, active, label, status, className }: HudFrameProps) {

    const cardRef = useRef<HTMLDivElement>(null);



    const handleMove = (e: React.MouseEvent<HTMLDivElement>) => {

        if (!cardRef.current || window.matchMedia("(pointer: coarse)").matches) return;

        const rect = cardRef.current.getBoundingClientRect();

        const px = (e.clientX - rect.left) / rect.width - 0.5;

        const py = (e.clientY - rect.top) / rect.height - 0.5;

        cardRef.current.style.transform = `perspective(1000px) rotateX(${py * -6}deg) rotateY(${px * 8}deg) translateZ(0)`;

    };



    const handleLeave = () => {

        if (!cardRef.current) return;

        cardRef.current.style.transform = "perspective(1000px) rotateX(0deg) rotateY(0deg)";

    };



    return (

        <div

            className={`hud-outer ${className ?? ""}`}

            style={{ perspective: "1000px" }}

            onMouseMove={handleMove}

            onMouseLeave={handleLeave}

        >

            <div ref={cardRef} className="hud-card" style={{ borderColor: accent, ["--hud-accent" as any]: accent }}>

                {(label || status) && (

                    <div className="hud-topbar">

                        {label && <span className="hud-label">{label}</span>}

                        {status && <span className="hud-status" style={{ color: accent }}>{status}</span>}

                    </div>

                )}



                <div className="hud-body">{children}</div>



                {/* targeting-computer corner brackets */}

                {["tl", "tr", "bl", "br"].map((c) => (

                    <span key={c} className={`hud-corner hud-corner-${c}`} style={{ borderColor: accent }} />

                ))}



                {active && <div className="hud-sweep" style={{ background: `linear-gradient(180deg, transparent, ${accent}55, transparent)` }} />}

            </div>



            <style jsx>{`

                .hud-outer { height: 100%; transform-style: preserve-3d; }

                .hud-card {

                    position: relative;

                    height: 100%;

                    display: flex;

                    flex-direction: column;

                    border: 1px solid;

                    border-radius: 10px;

                    background: linear-gradient(160deg, var(--color-gunmetal) 0%, color-mix(in srgb, var(--color-gunmetal) 92%, black) 100%);

                    box-shadow: 0 0 0 1px color-mix(in srgb, var(--hud-accent) 25%, transparent), 0 20px 60px -20px black, inset 0 0 40px -20px var(--hud-accent);

                    transition: transform 120ms ease-out, box-shadow 300ms ease;

                    overflow: hidden;

                    will-change: transform;

                }

                .hud-topbar {

                    display: flex;

                    justify-content: space-between;

                    align-items: center;

                    padding: 10px 16px;

                    border-bottom: 1px solid color-mix(in srgb, var(--hud-accent) 30%, var(--color-steel));

                    font-family: var(--font-nav);

                    font-size: 11px;

                    letter-spacing: 0.08em;

                    text-transform: uppercase;

                }

                .hud-label { color: var(--color-text-dim); }

                .hud-body { flex: 1; min-height: 0; position: relative; }

                .hud-corner {

                    position: absolute;

                    width: 16px;

                    height: 16px;

                    border-style: solid;

                    border-width: 0;

                    opacity: 0.9;

                    filter: drop-shadow(0 0 4px var(--hud-accent));

                    pointer-events: none;

                }

                .hud-corner-tl { top: 6px; left: 6px; border-top-width: 2px; border-left-width: 2px; }

                .hud-corner-tr { top: 6px; right: 6px; border-top-width: 2px; border-right-width: 2px; }

                .hud-corner-bl { bottom: 6px; left: 6px; border-bottom-width: 2px; border-left-width: 2px; }

                .hud-corner-br { bottom: 6px; right: 6px; border-bottom-width: 2px; border-right-width: 2px; }

                .hud-sweep {

                    position: absolute;

                    left: 0; right: 0;

                    height: 40%;

                    animation: sweep 2.4s linear infinite;

                    pointer-events: none;

                    mix-blend-mode: screen;

                }

                @keyframes sweep {

                    0% { top: -40%; }

                    100% { top: 100%; }

                }

                @media (prefers-reduced-motion: reduce) {

                    .hud-sweep { display: none; }

                    .hud-card { transition: none; }

                }

            `}</style>

        </div>

    );

}

"use client";

import { memo, useCallback, useEffect, useRef } from "react";

// 16-bit color palette (reduced color options)
const STAR_COLORS = [
  "#FFFFFF", // White
  "#FFFFAA", // Light yellow
  "#AAAAFF", // Light blue
  "#FFAAAA", // Light red
  "#AAFFAA", // Light green
  "#FFAAFF", // Light purple
  "#AAFFFF", // Light cyan
] as const;

// Configuration constants
const starDensity = 0.00004; // Reduced density for larger stars
const twinkleProbability = 0.7;
const minTwinkleSpeed = 2;
const maxTwinkleSpeed = 4;
const pixelSize = 5;
const starRegenerationInterval = 5000; // Interval to regenerate stars (in ms)
const percentToRegenerate = 0.15; // Percentage of stars to regenerate at each interval

// Shooting star configuration
const shootingStarPixelSize = 2;
const targetFps = 16; // 16 FPS for that retro feel

// Type definitions
type BackgroundStar = {
  x: number;
  y: number;
  color: string;
  baseOpacity: number;
  currentOpacity: number;
  twinkle: boolean;
  twinkleSpeed: number;
  twinkleDirection: number; // -1 fading out, 1 fading in
  twinkleTimer: number;
};

type TrailPoint = {
  x: number;
  y: number;
  opacity: number;
};

type ShootingStar = {
  id: number;
  x: number;
  y: number;
  angle: number;
  scale: number;
  speed: number;
  distance: number;
  trail: TrailPoint[];
};

type StartPoint = {
  x: number;
  y: number;
  angle: number;
};

export const BackgroundPixelStars = memo(
  () => {
    const canvasRef = useRef<HTMLCanvasElement | null>(null);
    const animationFrameRef = useRef<number | null>(null);

    // State references
    const backgroundStarsRef = useRef<BackgroundStar[]>([]);
    const shootingStarsRef = useRef<ShootingStar[]>([]);
    const lastRenderTimeRef = useRef<number>(0);
    const frameInterval: number = 1000 / targetFps;

    // Get random starting point for shooting stars
    const getRandomStartPoint = useCallback((): StartPoint => {
      // Start from anywhere along the top edge
      const x = Math.random() * window.innerWidth;

      // Randomize the angle with a wider range (45-135 degrees)
      // 90 degrees is straight down
      // 45 degrees is down-right, 135 degrees is down-left
      const angle = 45 + Math.random() * 90;

      return { x, y: 0, angle };
    }, []);

    // Create a new shooting star
    const createNewShootingStar = useCallback((): ShootingStar => {
      const { x, y, angle } = getRandomStartPoint();
      return {
        id: Date.now(),
        x,
        y,
        angle,
        scale: 1,
        speed: Math.random() * 5 + 8,
        distance: 0,
        trail: [], // Empty trail initially
      };
    }, [getRandomStartPoint]);

    // Initialize background stars
    const initBackgroundStars = useCallback((): void => {
      if (!canvasRef.current) return;

      const canvas = canvasRef.current;

      // Clear existing stars
      backgroundStarsRef.current = [];

      // Generate new stars
      const area = canvas.width * canvas.height;
      const numStars = Math.floor(area * starDensity);

      for (let i = 0; i < numStars; i++) {
        const shouldTwinkle = Math.random() < twinkleProbability;
        const gridX = Math.floor(Math.random() * (canvas.width / pixelSize)) * pixelSize;
        const gridY = Math.floor(Math.random() * (canvas.height / pixelSize)) * pixelSize;
        const colorIndex = Math.floor(Math.random() * STAR_COLORS.length);
        const baseOpacity = Math.random() * 0.5 + 0.5;

        backgroundStarsRef.current.push({
          x: gridX,
          y: gridY,
          color: STAR_COLORS[colorIndex]!,
          baseOpacity,
          currentOpacity: baseOpacity,
          twinkle: shouldTwinkle,
          twinkleSpeed: minTwinkleSpeed + Math.random() * (maxTwinkleSpeed - minTwinkleSpeed),
          twinkleDirection: -1, // -1 fading out, 1 fading in
          twinkleTimer: 0,
        });
      }
    }, []);

    // Regenerate a portion of background stars
    const regenerateBackgroundStars = useCallback((): void => {
      if (!canvasRef.current || backgroundStarsRef.current.length === 0) return;

      const canvas = canvasRef.current;
      const numToRegenerate = Math.max(
        1,
        Math.floor(backgroundStarsRef.current.length * percentToRegenerate),
      );

      for (let i = 0; i < numToRegenerate; i++) {
        const randomIndex = Math.floor(Math.random() * backgroundStarsRef.current.length);

        // Replace with a new star
        const shouldTwinkle = Math.random() < twinkleProbability;
        const gridX = Math.floor(Math.random() * (canvas.width / pixelSize)) * pixelSize;
        const gridY = Math.floor(Math.random() * (canvas.height / pixelSize)) * pixelSize;
        const colorIndex = Math.floor(Math.random() * STAR_COLORS.length);
        const baseOpacity = Math.random() * 0.5 + 0.5;

        backgroundStarsRef.current[randomIndex] = {
          x: gridX,
          y: gridY,
          color: STAR_COLORS[colorIndex]!,
          baseOpacity,
          currentOpacity: baseOpacity,
          twinkle: shouldTwinkle,
          twinkleSpeed: minTwinkleSpeed + Math.random() * (maxTwinkleSpeed - minTwinkleSpeed),
          twinkleDirection: -1,
          twinkleTimer: 0,
        };
      }
    }, []);

    // Main animation loop
    const animateCanvas = useCallback(
      (timestamp: number): void => {
        // Skip frames to limit to target FPS
        if (timestamp - lastRenderTimeRef.current < frameInterval) {
          animationFrameRef.current = requestAnimationFrame(animateCanvas);
          return;
        }

        lastRenderTimeRef.current = timestamp;

        if (!canvasRef.current) {
          animationFrameRef.current = requestAnimationFrame(animateCanvas);
          return;
        }

        const canvas = canvasRef.current;
        const ctx = canvas.getContext("2d");

        if (!ctx) {
          animationFrameRef.current = requestAnimationFrame(animateCanvas);
          return;
        }

        // Clear canvas
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // 1. Draw and update background stars
        backgroundStarsRef.current.forEach((star) => {
          ctx.fillStyle = star.color;
          ctx.globalAlpha = star.currentOpacity;
          ctx.fillRect(star.x, star.y, pixelSize, pixelSize);

          // Update twinkling
          if (star.twinkle) {
            // Update twinkle timer
            star.twinkleTimer += 1 / targetFps;

            if (star.twinkleTimer >= star.twinkleSpeed) {
              star.twinkleTimer = 0;
              star.twinkleDirection *= -1; // Reverse direction
            }

            // Calculate new opacity based on discrete steps
            const progress = star.twinkleTimer / star.twinkleSpeed;
            if (progress < 0.5) {
              star.currentOpacity =
                star.twinkleDirection < 0 ? star.baseOpacity : star.baseOpacity * 0.3;
            } else {
              star.currentOpacity =
                star.twinkleDirection < 0 ? star.baseOpacity * 0.3 : star.baseOpacity;
            }
          }
        });

        // 2. Update shooting stars
        if (shootingStarsRef.current.length) {
          shootingStarsRef.current = shootingStarsRef.current
            .map((star) => {
              // Calculate new position
              const newX = star.x + star.speed * Math.cos((star.angle * Math.PI) / 180);
              const newY = star.y + star.speed * Math.sin((star.angle * Math.PI) / 180);
              const newDistance = star.distance + star.speed;

              // Add current position to trail
              const newTrail = [...star.trail];

              // Only add to trail every few frames for pixelated effect
              if (newDistance % 8 < star.speed) {
                newTrail.push({
                  x: star.x,
                  y: star.y,
                  opacity: 1.0,
                });
              }

              // Update trail opacity and remove old trail pieces
              const updatedTrail = newTrail
                .map((point) => ({ ...point, opacity: point.opacity - 0.1 }))
                .filter((point) => point.opacity > 0);

              return {
                ...star,
                x: newX,
                y: newY,
                distance: newDistance,
                trail: updatedTrail,
              };
            })
            .filter(
              (star) =>
                // Remove stars that are out of bounds
                star.x >= -30 &&
                star.x <= window.innerWidth + 30 &&
                star.y >= -30 &&
                star.y <= window.innerHeight + 30,
            );

          // 3. Draw shooting stars
          shootingStarsRef.current.forEach((star) => {
            // Draw trail
            star.trail.forEach((point) => {
              ctx.save();
              ctx.translate(point.x, point.y);
              ctx.rotate((star.angle * Math.PI) / 180);
              ctx.translate(-point.x, -point.y);

              ctx.fillStyle = `rgba(180, 242, 255, ${point.opacity})`;
              ctx.fillRect(point.x, point.y, shootingStarPixelSize, shootingStarPixelSize);

              ctx.restore();
            });

            // Draw star (pixelated representation)
            const starWidth = 4; // 4 pixels wide
            const starHeight = 2; // 2 pixels high

            ctx.save();
            ctx.translate(star.x, star.y);
            ctx.rotate((star.angle * Math.PI) / 180);
            ctx.translate(-star.x, -star.y);

            ctx.fillStyle = "#ffffff";
            ctx.globalAlpha = 1.0;

            for (let y = 0; y < starHeight; y++) {
              for (let x = 0; x < starWidth; x++) {
                // Skip some pixels for pixelated look
                if ((x === 0 && y === 1) || (x === 3 && y === 0)) continue;

                ctx.fillRect(
                  star.x + x * shootingStarPixelSize,
                  star.y + y * shootingStarPixelSize,
                  shootingStarPixelSize,
                  shootingStarPixelSize,
                );
              }
            }

            ctx.restore();
          });
        }

        animationFrameRef.current = requestAnimationFrame(animateCanvas);
      },
      [frameInterval],
    );

    // Initialize the component
    useEffect(() => {
      if (!canvasRef.current) return;

      // Set canvas dimensions
      canvasRef.current.width = window.innerWidth;
      canvasRef.current.height = window.innerHeight;

      // Initialize background stars
      initBackgroundStars();

      // Start animation loop
      animationFrameRef.current = requestAnimationFrame(animateCanvas);

      // Create shooting stars periodically
      const createShootingStar = (): void => {
        const newStar = createNewShootingStar();
        shootingStarsRef.current = [...shootingStarsRef.current, newStar];

        // Set a random delay for creating the next star
        const randomDelay = Math.random() * 4000 + 2000; // 2-6 seconds
        setTimeout(createShootingStar, randomDelay);
      };

      // Create first shooting star
      createShootingStar();

      // Set up regeneration interval for background stars
      const regenerationInterval = setInterval(regenerateBackgroundStars, starRegenerationInterval);

      // Handle window resize
      const handleResize = (): void => {
        if (canvasRef.current) {
          canvasRef.current.width = window.innerWidth;
          canvasRef.current.height = window.innerHeight;
          initBackgroundStars();
        }
      };

      window.addEventListener("resize", handleResize);

      // Cleanup
      return () => {
        if (animationFrameRef.current) {
          cancelAnimationFrame(animationFrameRef.current);
        }
        clearInterval(regenerationInterval);
        window.removeEventListener("resize", handleResize);
      };
    }, [animateCanvas, createNewShootingStar, initBackgroundStars, regenerateBackgroundStars]);

    return <canvas ref={canvasRef} className="pointer-events-none fixed inset-0" />;
  },
  () => true,
);

export default BackgroundPixelStars;

