const KEY_SOUNDS_UP: Record<string, [number, number]> = {
    A: [31632, 80], B: [40736, 95], C: [39732, 85], D: [32577, 80],
    E: [23402, 80], F: [33063, 80], G: [33553, 85], H: [34081, 85],
    I: [25890, 85], J: [34515, 85], K: [35027, 85], L: [35510, 85],
    M: [41710, 85], N: [41198, 85], O: [26394, 80], P: [26889, 80],
    Q: [22345, 85], R: [23912, 85], S: [32121, 80], T: [24392, 85],
    U: [25413, 85], V: [40236, 85], W: [22880, 85], X: [39228, 70],
    Y: [24911, 85], Z: [38779, 75], " ": [51691, 130], "-": [42689, 85],
    "@": [23402, 80], "/": [42689, 85], ".": [42689, 85], ":": [42689, 85],
    "0": [26394, 80], "1": [25413, 85], "2": [23402, 80], "3": [23912, 85],
    "4": [24392, 85], "5": [24911, 85], "6": [25413, 85], "7": [25890, 85],
    "8": [26394, 80], "9": [26889, 80], Enter: [19180, 100],
};

function useAudio(enabled: boolean) {
    const ctxRef = useRef<AudioContext | null>(null);
    const bufferRef = useRef<AudioBuffer | null>(null);
    const readyRef = useRef(false);

    useEffect(() => {
        if (!enabled) return;
        const init = async () => {
            try {
                ctxRef.current = new AudioContext();
                const res = await fetch("/sounds/sound.ogg");
                if (!res.ok) return;
                bufferRef.current = await ctxRef.current.decodeAudioData(await res.arrayBuffer());
                readyRef.current = true;
            } catch {
                /* keystroke sound is a nicety, fail silently */
            }
        };
        init();
        return () => {
            ctxRef.current?.close();
        };
    }, [enabled]);

    const playSound = (sound: [number, number] | undefined) => {
        if (!readyRef.current || !ctxRef.current || !bufferRef.current || !sound) return;
        if (ctxRef.current.state === "suspended") ctxRef.current.resume();
        const src = ctxRef.current.createBufferSource();
        src.buffer = bufferRef.current;
        src.connect(ctxRef.current.destination);
        src.start(0, sound[0] / 1000, sound[1] / 1000);
    };

    const down = (key: string) => playSound(KEY_SOUNDS_DOWN[key.toUpperCase()] || KEY_SOUNDS_DOWN[key]);
    const up = (key: string) => playSound(KEY_SOUNDS_UP[key.toUpperCase()] || KEY_SOUNDS_UP[key]);

    return { down, up };
}

function useInView(ref: React.RefObject<HTMLElement | null>, once = true) {
    const [inView, setInView] = useState(false);
    const triggered = useRef(false);

    useEffect(() => {
        const el = ref.current;
        if (!el || (once && triggered.current)) return;

        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting && !triggered.current) {
                    setInView(true);
                    if (once) {
                        triggered.current = true;
                        observer.disconnect();
                    }
                }
            },
            { threshold: 0.1 }
        );
        observer.observe(el);
        return () => observer.disconnect();
    }, [ref, once]);

    return inView;
}

type TokenType = "command" | "flag" | "string" | "number" | "operator" | "path" | "variable" | "comment" | "default";
interface Token {
    type: TokenType;
    value: string;
}

function tokenizeBash(text: string): Token[] {
    const tokens: Token[] = [];
    const words = text.split(/(\s+)/);
    let isFirstWord = true;

    for (const word of words) {
        if (/^\s+$/.test(word)) {
            tokens.push({ type: "default", value: word });
            continue;
        }
        if (word.startsWith("#")) {
            tokens.push({ type: "comment", value: word });
            continue;
        }
        if (word.startsWith("$")) {
            tokens.push({ type: "variable", value: word });
            isFirstWord = false;
            continue;
        }
        if (word.startsWith("--") || word.startsWith("-")) {
            tokens.push({ type: "flag", value: word });
            isFirstWord = false;
            continue;
        }
        if (/^["'].*["']$/.test(word)) {
            tokens.push({ type: "string", value: word });
            isFirstWord = false;
            continue;
        }
        if (/^\d+$/.test(word)) {
            tokens.push({ type: "number", value: word });
            isFirstWord = false;
            continue;
        }
        if (/^[|>&<]+$/.test(word)) {
            tokens.push({ type: "operator", value: word });
            isFirstWord = true;
            continue;
        }
        if (word.includes("/") || word.startsWith(".") || word.startsWith("~")) {
            tokens.push({ type: "path", value: word });
            isFirstWord = false;
            continue;
        }
        if (isFirstWord) {
            tokens.push({ type: "command", value: word });
            isFirstWord = false;
            continue;
        }
        tokens.push({ type: "default", value: word });
    }

    return tokens;
}

const tokenColors: Record<TokenType, string> = {
    command: "text-emerald-400",
    flag: "text-sky-400",
    string: "text-amber-300",
    number: "text-purple-400",
    operator: "text-red-400",
    path: "text-cyan-300",
    variable: "text-pink-400",
    comment: "text-neutral-500",
    default: "text-neutral-300",
};

function SyntaxHighlightedText({ text }: { text: string }) {
    const tokens = tokenizeBash(text);
    return (
        <>
            {tokens.map((token, i) => (
                <span key={i} className={tokenColors[token.type]}>
                    {token.value}
                </span>
            ))}
        </>
    );
}

interface TerminalLine {
    type: "command" | "output";
    content: string;
}

export interface TerminalProps {
    commands: string[];
    outputs?: Record<number, string[]>;
    username?: string;
    className?: string;
    typingSpeed?: number;
    delayBetweenCommands?: number;
    initialDelay?: number;
    enableSound?: boolean;
}

export function Terminal({
    commands = ["whoami"],
    outputs = {},
    username = "isb-terminal",
    className,
    typingSpeed = 50,
    delayBetweenCommands = 800,
    initialDelay = 500,
    enableSound = true,
}: TerminalProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const inView = useInView(containerRef);
    const { down, up } = useAudio(enableSound);

    const [lines, setLines] = useState<TerminalLine[]>([]);
    const [currentText, setCurrentText] = useState("");
    const [commandIdx, setCommandIdx] = useState(0);
    const [charIdx, setCharIdx] = useState(0);
    const [outputIdx, setOutputIdx] = useState(-1);
    const [phase, setPhase] = useState<"idle" | "typing" | "executing" | "outputting" | "pausing" | "done">("idle");
    const [cursorVisible, setCursorVisible] = useState(true);

    const currentCommand = commands[commandIdx] || "";
    const currentOutputs = useMemo(() => outputs[commandIdx] || [], [outputs, commandIdx]);
    const isLastCommand = commandIdx === commands.length - 1;

    useEffect(() => {
        if (!inView || phase !== "idle") return;
        const t = setTimeout(() => setPhase("typing"), initialDelay);
        return () => clearTimeout(t);
    }, [inView, phase, initialDelay]);

    useEffect(() => {
        if (phase !== "typing") return;
        if (charIdx < currentCommand.length) {
            const char = currentCommand[charIdx];
            down(char);
            const t = setTimeout(() => {
                up(char);
                setCurrentText(currentCommand.slice(0, charIdx + 1));
                setCharIdx((c) => c + 1);
            }, typingSpeed + Math.random() * 30);
            return () => clearTimeout(t);
        } else {
            down("Enter");
            const t = setTimeout(() => {
                up("Enter");
                setPhase("executing");
            }, 80);
            return () => clearTimeout(t);
        }
    }, [phase, charIdx, currentCommand, typingSpeed, down, up]);

    useEffect(() => {
        if (phase !== "executing") return;
        setLines((prev) => [...prev, { type: "command", content: currentCommand }]);
        setCurrentText("");
        if (currentOutputs.length > 0) {
            setOutputIdx(0);
            setPhase("outputting");
        } else if (isLastCommand) {
            setPhase("done");
        } else {
            setPhase("pausing");
        }
    }, [phase, currentCommand, currentOutputs.length, isLastCommand]);

    useEffect(() => {
        if (phase !== "outputting") return;
        if (outputIdx >= 0 && outputIdx < currentOutputs.length) {
            const t = setTimeout(() => {
                setLines((prev) => [...prev, { type: "output", content: currentOutputs[outputIdx] }]);
                setOutputIdx((i) => i + 1);
            }, 150);
            return () => clearTimeout(t);
        } else if (outputIdx >= currentOutputs.length) {
            const t = setTimeout(() => {
                setPhase(isLastCommand ? "done" : "pausing");
            }, 300);
            return () => clearTimeout(t);
        }
    }, [phase, outputIdx, currentOutputs, isLastCommand]);

    useEffect(() => {
        if (phase !== "pausing") return;
        const t = setTimeout(() => {
            setCharIdx(0);
            setOutputIdx(-1);
            setCommandIdx((c) => c + 1);
            setPhase("typing");
        }, delayBetweenCommands);
        return () => clearTimeout(t);
    }, [phase, delayBetweenCommands]);

    useEffect(() => {
        const interval = setInterval(() => setCursorVisible((v) => !v), 530);
        return () => clearInterval(interval);
    }, []);

    useEffect(() => {
        if (contentRef.current) contentRef.current.scrollTop = contentRef.current.scrollHeight;
    }, [lines, phase]);

    const prompt = (
        <span className="text-neutral-500">
            <span className="text-sky-500">{username}</span>
            <span className="text-emerald-600">:</span>
            <span className="text-sky-400">~</span>
            <span className="text-neutral-500">$</span>{" "}
        </span>
    );

    return (
        <div ref={containerRef} className={cn("mx-auto w-full max-w-xl px-4 font-mono text-xs", className)}>
            <div className="overflow-hidden rounded-lg border border-neutral-800 bg-neutral-900 shadow-2xl">
                <div className="flex items-center gap-2 bg-neutral-800 px-4 py-3">
                    <div className="flex items-center gap-1.5">
                        <div className="h-3 w-3 rounded-full bg-red-500 transition-colors hover:bg-red-600" />
                        <div className="h-3 w-3 rounded-full bg-yellow-500 transition-colors hover:bg-yellow-600" />
                        <div className="h-3 w-3 rounded-full bg-green-500 transition-colors hover:bg-green-600" />
                    </div>
                    <div className="flex-1 text-center">
                        <span className="truncate text-xs text-neutral-400">{username} — bash</span>
                    </div>
                    <div className="w-[52px]" />
                </div>

                <div ref={contentRef} className="no-visible-scrollbar h-80 overflow-y-auto p-4 font-mono">
                    {lines.map((line, i) => (
                        <div key={i} className="leading-relaxed whitespace-pre-wrap">
                            {line.type === "command" ? (
                                <span>
                                    {prompt}
                                    <SyntaxHighlightedText text={line.content} />
                                </span>
                            ) : (
                                <span className="text-neutral-400">{line.content}</span>
                            )}
                        </div>
                    ))}

                    {phase === "typing" && (
                        <div className="leading-relaxed whitespace-pre-wrap">
                            {prompt}
                            <SyntaxHighlightedText text={currentText} />
                            <span className="ml-0.5 inline-block h-4 w-2 bg-neutral-300 align-middle" />
                        </div>
                    )}

                    {(phase === "done" || phase === "pausing" || phase === "outputting") && (
                        <div className="leading-relaxed whitespace-pre-wrap">
                            {prompt}
                            <span
                                className={cn(
                                    "inline-block h-4 w-2 bg-neutral-300 align-middle transition-opacity duration-100",
                                    !cursorVisible && "opacity-0"
                                )}
                            />
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
}
